def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def kthLargestLevelSum(tree, k):
    vals, left, right = _links(tree)
    n = len(vals)
    depth = [0] * n
    sums = []
    for i in range(n):
        d = depth[i]
        if d == len(sums):
            sums.append(0)
        sums[d] += vals[i]
        for c in (left[i], right[i]):
            if c != -1:
                depth[c] = d + 1
    if len(sums) < k:
        return -1
    sums.sort(reverse=True)
    return sums[k - 1]
